            }
          },
          {
            "item": "viz_13",
            "type": "block",
            "position": {
              "x": 20,
              "y": 1174,
              "w": 1420,
              "h": 96
            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Volumetric DDoS indicators",
          "layoutId": "layout_1"
        }
      ]
    }
  },
  "expressions": {},
  "applicationProperties": {
    "hideEdit": false,
    "hideExport": false
  }
}
